kKicker: "SUKI KAMPUNG · கட்டம் 1",
kTitle: "ஒன்றாக விளையாடுங்கள். ஒன்றாக உருவாக்குங்கள். ஒன்றாக வளருங்கள்.",
kDesc: "தென்கிழக்கு சுலாவேசி பாணியில் வெப்பமண்டல மெய்நிகர் கிராமத்தை உருவாக்குங்கள்: கட்டிடங்களை வைக்கவும், SUKI நாணயங்களை அறுவடை செய்யவும், தினசரி பணிகளை முடிக்கவும், சுல்ட்ரா வினாடி வினாவில் அறிவை சோதிக்கவும்.",
kBack: "← SUKI க்குத் திரும்புக",
kBackAria: "SUKI முகப்புக்குத் திரும்புக",
kDemoB: "டெமோ பயன்முறை",
kDemoT: "— கிராம முன்னேற்றம் இந்த சாதனத்தில் சேமிக்கப்படுகிறது, உங்கள் SUKI கணக்கில் அல்ல. பின்தளம் (அங்கீகாரம், நண்பர்கள், சர்வர்-பக்க பரிந்துரை) இன்னும் செயல்படுத்தப்படவில்லை.",
kFrameTitle: "SUKI Kampung விளையாட்டு — கட்டம் 1 விளையாடக்கூடிய முன்மாதிரி",
kNoJs: "SUKI Kampung விளையாட JavaScript தேவை.",
kFootnote: "இந்த விளையாட்டில் SUKI நாணயங்கள் மெய்நிகர் சொத்துகள், உண்மையான பணம் அல்ல, திரும்பப் பெற முடியாது. பின்தள நிலையை /api/kampung/status இல் பார்க்கவும்.",
