bLandAudKicker: "உங்கள் அடுத்த அடிக்காக உருவாக்கப்பட்டது",
bLandAudTitle: "வளர பல வழிகளுக்கு ஒரே இடம்.",
bLandAudDesc: "மிக அருகிலுள்ள தேவையிலிருந்து தொடங்கி, திசையுடன் இருப்பை உருவாக்குங்கள்.",
bLandAud1t: "விற்பனையாளர்கள் & சிறு நிறுவனங்கள்",
bLandAud1d: "உங்கள் தயாரிப்புகள், சேவைகள், வணிகக் கதைக்கு ஏற்ற இடத்தைக் கண்டறியுங்கள்.",
bLandAud2t: "சொத்து & டெவலப்பர்கள்",
bLandAud2d: "உங்கள் திட்டங்களையும் இடங்களையும் உள்ளூர் வாங்குபவர்கள் எளிதில் புரிந்துகொள்ளச் செய்யுங்கள்.",
