/** Ambil label groups/business/kampung untuk bahasa aktif (fallback ke Indonesia). */
export function getGroupsLabels(language: string): Record<string, string> {
  return dictGroups[language] ?? dictGroups.id;
}

/** Daftar kunci groups/business/kampung (untuk validasi kelengkapan terjemahan). */
export const GROUPS_KEYS = Object.keys(dictGroups.id);
